"""Chapter 4's boss_move task must carry a concrete 四季王 site (docich#5421).

``chart.boss_castle(4)`` answers 'ボス' for every chapter, but chapter 4 has
no 'ボス' castle: the four 四季王 sites are the boss. The monthly roster
marker already measured which site the general is camped at; that name is
the only safe Y-jump destination.
"""
from docich.hanjuku_speedrun.hanjuku.flows import post_month_status as post


def _camper(candidate):
    marker = {'castle_candidate': candidate} if candidate else {}
    return {'location': 'camp', 'hp': 30, 'max_hp': 30, 'broken': False,
            'marker': marker}


def test_chapter_four_boss_move_carries_the_measured_site():
    statuses = {'リーキ': _camper('四季王城(北東)')}
    assert post._tasks(statuses, list(statuses), chapter=4) == [
        {'kind': 'boss_move', 'name': 'リーキ', 'goal': '四季王城(北東)'}]


def test_chapter_four_without_a_site_keeps_the_exemption_but_never_guesses():
    # The roster can only bind the shared label 'ボス' (no chapter-4 cell):
    # keep the siege exemption instead of a boss_move aimed at 'ボス'.
    statuses = {'リーキ': _camper('ボス')}
    assert post._tasks(statuses, list(statuses), chapter=4) == []


def test_other_chapters_keep_the_single_boss_castle_goal():
    statuses = {'ゼウス': _camper('けっかい')}
    assert post._tasks(statuses, list(statuses), chapter=1) == [
        {'kind': 'boss_move', 'name': 'ゼウス', 'goal': 'けっかい'}]
